def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

    def forward(self, x):
        assert x.is_cuda, "Input must be on CUDA device"
        x = x.contiguous()
        weight = self.conv1.weight.contiguous()
        bias = self.conv1.bias.contiguous()

        N, C, H, W = x.shape
        OC = self.out_channels
        K = self.kernel_size
        S = self.stride
        P = self.padding

        OH = (H + 2 * P - K) // S + 1
        OW = (W + 2 * P - K) // S + 1

        output = torch.empty((N, OC, OH, OW), dtype=x.dtype, device=x.device)

        total_elements = N * OC * OH * OW

        block_size = 256
        grid_x = (total_elements + block_size - 1) // block_size

        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=(grid_x, 1, 1),
            block=(block_size, 1, 1),
            arguments=[x, weight, bias, output, i32(total_elements)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output
